import{_ as e,o as a,c as n,a4 as r}from"./chunks/framework.BAxM5-cj.js";const u=JSON.parse('{"title":"Sprint 10 — Content Requests & Calendar","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_10_Content_Requests_Calendar.md","filePath":"plan/sprints/Sprint_10_Content_Requests_Calendar.md"}'),i={name:"plan/sprints/Sprint_10_Content_Requests_Calendar.md"};function s(d,t,o,l,c,p){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="sprint-10-—-content-requests-calendar" tabindex="-1">Sprint 10 — Content Requests &amp; Calendar <a class="header-anchor" href="#sprint-10-—-content-requests-calendar" aria-label="Permalink to &quot;Sprint 10 — Content Requests &amp; Calendar&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 19–20 (Sep 23–Oct 6, 2026) <strong>Jira:</strong> DA Sprint 10 <strong>Phase:</strong> Phase 5 — Content Workflow &amp; Publishing <strong>Goal:</strong> Implement the content request lifecycle, task assignment to Content Creators, and the content calendar with drag-drop scheduling.</p><p>&gt; <strong>AI Parallel:</strong> AI Iteration 3 runs concurrently this sprint (final week).</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E28</td><td>Content Request Management</td><td>Trung</td></tr><tr><td>E29</td><td>Task Assignment &amp; Tracking</td><td>Trung, Ân</td></tr><tr><td>E30</td><td>Content Calendar &amp; Scheduling</td><td>Trung, Lộc</td></tr></tbody></table><p><strong>Note on Epic numbering:</strong> Epics E25–E27 are reserved for potential scope expansion. No tasks are missing.</p><p><strong>Deliverables by end of Sprint 10:</strong></p><ul><li>BRAND_CLIENT can submit content requests</li><li>ACCOUNT_MANAGER can view and assign requests to Content Creators</li><li>CONTENT_CREATOR can view their task list</li><li>Deadline alert notifications working</li><li>Content calendar shows posts by date range</li><li>ACCOUNT_MANAGER can schedule a post (set scheduledAt + target platforms)</li><li>ContentCalendar React component with drag-drop</li><li>PlatformPreview component</li></ul><hr><h2 id="epic-e28-—-content-request-management" tabindex="-1">EPIC E28 — Content Request Management <a class="header-anchor" href="#epic-e28-—-content-request-management" aria-label="Permalink to &quot;EPIC E28 — Content Request Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E28-01</td><td>Implement POST /api/v1/content-requests (BRAND_CLIENT submits request: topic, platform, tone, deadline)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E28-02</td><td>Implement GET /api/v1/content-requests (ACCOUNT_MANAGER views list of requests from their assigned clients)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E28-03</td><td>Implement status tracking (SUBMITTED → ASSIGNED → IN_PROGRESS → PENDING_REVIEW → SENT_TO_CLIENT → APPROVED → REJECTED)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>ContentRequest document fields:</strong><code>requestId</code>, <code>workspaceId</code>, <code>clientId</code>, <code>topic</code>, <code>platform[]</code>, <code>tone</code>, <code>deadline</code>, <code>status</code>, <code>assignedCreatorId</code>, <code>linkedPostId</code>, <code>createdAt</code>, <code>updatedAt</code></p><p><strong>Status transition rules:</strong></p><ul><li>BRAND_CLIENT: SUBMITTED only</li><li>ACCOUNT_MANAGER: SUBMITTED→ASSIGNED, PENDING_REVIEW→SENT_TO_CLIENT, SENT_TO_CLIENT→APPROVED/REJECTED</li><li>CONTENT_CREATOR: ASSIGNED→IN_PROGRESS, IN_PROGRESS→PENDING_REVIEW</li><li>System: SENT_TO_CLIENT→APPROVED/REJECTED (via client portal action)</li></ul><hr><h2 id="epic-e29-—-task-assignment-tracking" tabindex="-1">EPIC E29 — Task Assignment &amp; Tracking <a class="header-anchor" href="#epic-e29-—-task-assignment-tracking" aria-label="Permalink to &quot;EPIC E29 — Task Assignment &amp; Tracking&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E29-01</td><td>Implement PUT /api/v1/content-requests/{id}/assign (ACCOUNT_MANAGER assigns task to CONTENT_CREATOR)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E29-02</td><td>Implement GET /api/v1/content-requests/my-tasks (CONTENT_CREATOR views their assigned tasks)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E29-03</td><td>Implement deadline management (alert when a task is approaching its deadline)</td><td>Ân (AI)</td><td>🟡 High</td></tr></tbody></table><p><strong>Deadline alert (DA-E29-03):</strong></p><ul><li>Check every hour: query tasks where <code>deadline &lt; now + 24h AND status NOT IN [APPROVED, REJECTED]</code></li><li>Create notification for CONTENT_CREATOR (if IN_PROGRESS) or ACCOUNT_MANAGER (if SUBMITTED/ASSIGNED)</li><li>Also alert if <code>deadline &lt; now</code> (overdue): create OVERDUE notification</li></ul><hr><h2 id="epic-e30-—-content-calendar-scheduling" tabindex="-1">EPIC E30 — Content Calendar &amp; Scheduling <a class="header-anchor" href="#epic-e30-—-content-calendar-scheduling" aria-label="Permalink to &quot;EPIC E30 — Content Calendar &amp; Scheduling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E30-01</td><td>Implement GET /api/v1/posts/calendar (retrieve posts by date range, filter by platform/status)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E30-02</td><td>Implement POST /api/v1/posts/{id}/schedule (ACCOUNT_MANAGER sets schedule: scheduledAt + targetPlatforms)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E30-03</td><td>Build ContentCalendar React component (drag-drop rescheduling, color-coded status indicators)</td><td>Lộc (Frontend)</td><td>🔴 Critical</td></tr><tr><td>DA-E30-04</td><td>Build PlatformPreview component (display preview in the correct format for FB, IG, TikTok, Threads)</td><td>Lộc (Frontend)</td><td>🟡 High</td></tr></tbody></table><p><strong>Calendar API (DA-E30-01):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/posts/calendar?startDate=2026-10-01&amp;endDate=2026-10-31&amp;platform=FACEBOOK&amp;status=SCHEDULED</span></span>
<span class="line"><span>Response: [{postId, title, scheduledAt, platforms[], status, thumbnailUrl}]</span></span></code></pre></div><p><strong>ContentCalendar component (DA-E30-03):</strong></p><ul><li>Use <code>react-big-calendar</code> or <code>@fullcalendar/react</code> library</li><li>Color coding: DRAFT=gray, SCHEDULED=blue, PUBLISHED=green, FAILED=red, PENDING_REVIEW=yellow</li><li>Drag post to new date → calls <code>PUT /api/v1/posts/{id}/reschedule</code></li></ul><p><strong>PlatformPreview (DA-E30-04):</strong></p><ul><li>FB: 1200x630 link preview card format</li><li>IG: square (1:1) or portrait (4:5) image with caption below</li><li>TikTok: vertical (9:16) video thumbnail with overlay text</li><li>Threads: text post format, truncated at 500 chars</li></ul><p><strong>Notes:</strong></p><ul><li>Scheduling a post does NOT immediately enqueue to RabbitMQ — that happens when the post reaches APPROVED status (Sprint 11).</li><li><code>targetPlatforms</code> can be a subset of connected social accounts.</li></ul><hr><h2 id="sprint-10-checklist" tabindex="-1">Sprint 10 Checklist <a class="header-anchor" href="#sprint-10-checklist" aria-label="Permalink to &quot;Sprint 10 Checklist&quot;">​</a></h2><ul><li>[ ] BRAND_CLIENT can submit content request with topic, platform, tone, deadline</li><li>[ ] ACCOUNT_MANAGER sees all requests from their clients (not other clients)</li><li>[ ] Status transitions enforce role rules (BRAND_CLIENT cannot jump to ASSIGNED)</li><li>[ ] ACCOUNT_MANAGER can assign request to CONTENT_CREATOR</li><li>[ ] CONTENT_CREATOR sees only their assigned tasks</li><li>[ ] Deadline alert: notification 24h before deadline</li><li>[ ] Overdue alert: notification when deadline passes</li><li>[ ] Calendar API returns posts for date range with filters</li><li>[ ] Schedule API: sets scheduledAt + targetPlatforms on post</li><li>[ ] ContentCalendar React component renders with correct colors</li><li>[ ] Drag-drop reschedule calls API and updates calendar</li><li>[ ] PlatformPreview shows correct format for FB, IG, TikTok, Threads</li></ul>`,34)])])}const E=e(i,[["render",s]]);export{u as __pageData,E as default};
